
-- 初始化脚本：保留已有数据库、金融机构和登录账号。
-- 其余业务数据包含初始化操作，不应作为日常升级脚本重复导入生产库。
create database if not exists trans_finance
  default character set utf8mb4
  collate utf8mb4_0900_ai_ci;
use trans_finance;
set names utf8mb4;
set foreign_key_checks = 1;
set sql_safe_updates=0;


create table if not exists industry (
  id bigint primary key auto_increment comment '行业ID',
  industry_code varchar(32) not null comment '行业代码，如D44/C26',
  industry_name varchar(100) not null comment '行业名称',
  description varchar(500) null comment '行业说明',
  unique key uk_industry_code (industry_code)
) engine=InnoDB default charset=utf8mb4 comment='行业表';


-- 保留已有机构及其编码，避免已有账号关联失效。
create table if not exists financial_institution (
  institution_code varchar(64) primary key comment '金融机构编码',
  institution_name varchar(200) not null comment '金融机构名称',
  institution_type varchar(64) not null default 'bank' comment '机构类型：bank/guarantee/other',
  contact_name varchar(100) null comment '联系人',
  contact_phone varchar(30) null comment '联系电话'
) engine=InnoDB default charset=utf8mb4 comment='金融机构表';
on duplicate key update institution_code = financial_institution.institution_code;


create table if not exists electric_company_data (
  id bigint primary key auto_increment comment '数据ID',
  industry_code varchar(32) not null default 'D44' comment '行业代码',
  stock_code varchar(20) not null comment '股票代码',
  company_name varchar(200) not null comment '公司名称',
  data_year int not null comment '年份',
  company_year_key varchar(64) not null comment '企业年份键',
  carbon_market_included tinyint null comment '碳市场纳入',
  local_transition_policy_support tinyint null comment '地方转型金融政策支持',
  double_carbon_commitment tinyint null comment '双碳转型承诺目标',
  transition_plan_prepared tinyint null comment '转型计划编制',
  green_patent_ratio decimal(18,8) null comment '绿色专利授权数量占比',
  energy_environment_investment_intensity decimal(18,8) null comment '节能环保投资强度',
  non_two_high_revenue_ratio decimal(18,8) null comment '非两高业务收入占比',
  digital_technology_level decimal(18,8) null comment '数字技术应用水平',
  executive_compensation_esg_linked tinyint null comment '高管薪酬ESG挂钩',
  third_party_verification tinyint null comment '第三方核查',
  disclosure_quality decimal(18,8) null comment '信息披露质量',
  power_supply_coal_consumption decimal(18,8) null comment '供电煤耗',
  clean_energy_installed_capacity_ratio decimal(18,8) null comment '清洁能源装机占比',
  power_carbon_intensity decimal(18,8) null comment '度电碳排放强度',
  ccer_development_volume decimal(18,8) null comment 'CCER开发量',
  current_ratio decimal(18,8) null comment '流动比率',
  revenue_growth_rate decimal(18,8) null comment '营收增长率',
  cash_flow_ratio decimal(18,8) null comment '现金流比率',
  asset_liability_ratio decimal(18,8) null comment '资产负债率',
  roa decimal(18,8) null comment 'ROA',
  environmental_penalty_count decimal(18,8) null comment '环保处罚次数',
  industry_prosperity_index decimal(18,8) null comment '行业景气指数',
  carbon_price decimal(18,8) null comment '碳价',
  loan_granted tinyint not null comment '目标变量：是否获得贷款',
  key idx_ml_power_year (data_year),
  key idx_ml_power_label (loan_granted),
  constraint fk_ml_power_industry foreign key (industry_code) references industry(industry_code)
) engine=InnoDB default charset=utf8mb4 comment='电力行业企业历年转型数据表';








-- 重复初始化时保留已有账号和密码；新库账号由本地管理流程创建。
create table if not exists financial_institution_user (
  id bigint primary key auto_increment comment '金融机构用户ID',
  institution_id varchar(64) not null comment '所属金融机构编码',
  username varchar(64) not null comment '用户名',
  password_hash varchar(128) not null comment '密码'
) engine=InnoDB default charset=utf8mb4 comment='金融机构登录用户表';
-- 金融机构用户请在本地环境按需创建，避免将演示密码写入版本库。


