-- 2026-08-15 模型训练任务与模型元数据表

set names utf8mb4;

create table if not exists `model_training_job` (
  `id` bigint primary key auto_increment comment '训练任务ID',
  `institution_code` varchar(64) not null comment '金融机构编码',
  `job_type` varchar(30) not null comment '任务类型：train_all/update',
  `status` varchar(30) not null comment '任务状态：PENDING/RUNNING/SUCCESS/FAILED',
  `progress` int not null default 0 comment '训练进度，0-100',
  `message` varchar(500) null comment '任务说明',
  `total_models` int not null default 0 comment '计划训练模型数',
  `trained_models` int not null default 0 comment '已训练模型数',
  `started_at` datetime null comment '开始时间',
  `finished_at` datetime null comment '结束时间',
  `created_at` datetime not null default current_timestamp comment '创建时间',
  key `idx_training_job_institution` (`institution_code`, `created_at`)
) engine=InnoDB default charset=utf8mb4 comment='模型训练任务表';

create table if not exists `industry_model_metadata` (
  `id` bigint primary key auto_increment comment '模型元数据ID',
  `institution_code` varchar(64) not null comment '金融机构编码',
  `industry_key` varchar(64) not null comment '行业模型编码',
  `industry_name` varchar(100) not null comment '模型范围名称',
  `target_name` varchar(64) not null comment '目标变量：verified_transition_performance',
  `model_type` varchar(100) not null comment '模型类型',
  `model_path` varchar(500) not null comment '模型文件路径',
  `feature_columns_json` json null comment '特征字段列表',
  `feature_weights_json` json null comment '特征权重列表',
  `metrics_json` json null comment '模型训练评估指标',
  `sample_count` int not null default 0 comment '训练样本数',
  `company_count` int not null default 0 comment '训练企业数',
  `year_start` int null comment '训练集起始年份',
  `year_end` int null comment '训练集结束年份',
  `model_version` varchar(64) not null comment '模型版本',
  `status` varchar(30) not null comment '模型状态',
  `trained_at` datetime null comment '训练完成时间',
  `updated_at` datetime not null default current_timestamp on update current_timestamp comment '更新时间',
  unique key `uk_model_scope` (`institution_code`, `industry_key`, `target_name`),
  key `idx_model_institution` (`institution_code`, `industry_key`)
) engine=InnoDB default charset=utf8mb4 comment='行业模型元数据表';


-- =====================================================================
-- Source: database/20260815_pending_company_data.sql
-- =====================================================================
-- 2026-08-15 八行业待评估企业数据初始化脚本（历史版本）
-- 2026-08-26 起请改为执行 database/20260826_evaluation_data_refresh.sql，
-- 该脚本会删除旧待评估表并导入新的 2023-2025 数据。
-- 说明：
-- 1. 每张待评估表从对应已评估历史表复制结构后，删除两个目标变量列。
-- 2. 初始化数据取每个金融机构在该行业历史表中的最新年份数据。
-- 3. transition_score 与 green_loan_score 暂置为空，等待后续评估流程写入或计算。

set names utf8mb4;

drop procedure if exists init_pending_company_data_table;

delimiter //

create procedure init_pending_company_data_table(
    in source_table_name varchar(128),
    in pending_table_name varchar(128)
)
begin
    set @drop_sql = concat('drop table if exists `', pending_table_name, '`');
    prepare drop_stmt from @drop_sql;
    execute drop_stmt;
    deallocate prepare drop_stmt;

    set @create_sql = concat('create table `', pending_table_name, '` like `', source_table_name, '`');
    prepare create_stmt from @create_sql;
    execute create_stmt;
    deallocate prepare create_stmt;

    set @alter_sql = concat(
        'alter table `', pending_table_name, '` ',
        'drop column `green_loan`, ',
        'drop column `verified_transition_performance`, ',
        'auto_increment = 1'
    );
    prepare alter_stmt from @alter_sql;
    execute alter_stmt;
    deallocate prepare alter_stmt;

    select group_concat(concat('`', column_name, '`') order by ordinal_position)
      into @insert_columns
      from information_schema.columns
     where table_schema = database()
       and table_name = pending_table_name
       and column_name <> 'id';

    select group_concat(
               case
                   when column_name in ('transition_score', 'green_loan_score')
                       then concat('null as `', column_name, '`')
                   else concat('s.`', column_name, '`')
               end
               order by ordinal_position
           )
      into @select_columns
      from information_schema.columns
     where table_schema = database()
       and table_name = pending_table_name
       and column_name <> 'id';

    set @insert_sql = concat(
        'insert into `', pending_table_name, '` (', @insert_columns, ') ',
        'select ', @select_columns, ' ',
        'from `', source_table_name, '` s ',
        'join (',
        '  select coalesce(institution_code, institution_name) as institution_key, max(data_year) as max_year ',
        '  from `', source_table_name, '` ',
        '  group by coalesce(institution_code, institution_name)',
        ') latest ',
        '  on coalesce(s.institution_code, s.institution_name) <=> latest.institution_key ',
        ' and s.data_year = latest.max_year ',
        'order by coalesce(s.institution_code, s.institution_name), s.company_name, s.id'
    );
    prepare insert_stmt from @insert_sql;
    execute insert_stmt;
    deallocate prepare insert_stmt;
end //

